  `column_name_en_us` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Excel列头（英文）',
  `sort` bigint NOT NULL COMMENT '列顺序',
  `enabled` tinyint DEFAULT '1' COMMENT '是否启用（1=是0=否）',
  `entity` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据字段的uuid',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_table_field` (`table_name`,`field_name`)
